    });

    carrinhoTextoFormatado += `\n\n`;
  }

  carrinhoTextoFormatado += `----------------------------------------------------------\n\n`;

}

// 6. Trata o caso de o carrinho estar vazio (embora já validado no início).
if (carrinhoTextoFormatado === "") {
carrinhoTextoFormatado = "Sua Sacola está vazia.";
}

// 7. Retorna o texto formatado e o total.
return [{
json: {
carrinho_texto: carrinhoTextoFormatado,
total_valor: totalGeral.toFixed(2)
}
}];

// --- CÓDIGO CORRIGIDO PARA FORMATAR O CARRINHO E CALCULAR O TOTAL ---

// 1. Pega os dados de entrada
const sessao = $items("busca_carrinho_atual1")[0].json;
const carrinho = sessao.carrinho_json || [];
const mapa = sessao.mapa_id_json || {};
const dados = $items("Código para Verificar Apenas o Valor Mínimo1")[0].json

// 2. Garante que os dados estão no formato correto
let carrinhoArray = [];
if (Array.isArray(carrinho)) {
  carrinhoArray = carrinho;
} else if (typeof carrinho === 'string') {
  try {
    carrinhoArray = JSON.parse(carrinho);
  } catch (e) {
    carrinhoArray = [];
  }
}

let mapaObjeto = {};
if (typeof mapa === 'object' && mapa !== null) {
  mapaObjeto = mapa;
} else if (typeof mapa === 'string') {
  try {
    mapaObjeto = JSON.parse(mapa);
  } catch (e) {
    mapaObjeto = {};
  }
}

// 3. Validação
if (carrinhoArray.length === 0) {
  // Retorna uma resposta padrão para carrinho vazio
  return [{
    json: {
      Jid: sessao.jid,
      print_carrinho: "Sua Sacola está vazia.",
      mensagemResposta: "Sua Sacola está vazia.",
      totalComDesconto: "0.00",
      totalSemDesconto: "0.00"
    }
  }];
}

// 4. Prepara as variáveis
const valorDoCupom = dados.property_desconto;
// --- NOVA VARIÁVEL: LIMITE DO DESCONTO ---
// Pega o limite do desconto, convertendo para número. Se não existir, define como Infinity (sem limite).
const limiteDesconto = (dados.property_limite && parseFloat(dados.property_limite) > 0)
  ? parseFloat(dados.property_limite)
  : Infinity;

let totalGeral = 0;
let carrinhoTexto = "";

// --- INÍCIO DA CORREÇÃO LÓGICA ---

// 5. Cria um "mapa reverso" para encontrar o índice a partir do ID do item.
const mapaReverso = {};
for (const indice in mapaObjeto) {
  const idDoItem = mapaObjeto[indice].id;
  mapaReverso[idDoItem] = indice;
}

// 6. Loop CORRETO: Percorre o CARRINHO do cliente.
for (const itemNoCarrinho of carrinhoArray) {
  const subtotal = (itemNoCarrinho.qtd || 0) * (itemNoCarrinho.precoUnitario || 0);
  totalGeral += subtotal;

  const precoUnitarioFormatado = (itemNoCarrinho.precoUnitario || 0).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' }); 
  const subtotalFormatado = subtotal.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

  // --- CORREÇÃO --- // Pega o índice diretamente do item do carrinho, como você pediu.
  const indice = itemNoCarrinho.indice || "?"; 
  // --- FIM DA CORREÇÃO ---

  // Monta a string no formato que você pediu. 
  carrinhoTexto += `*${indice})* `;
  if (itemNoCarrinho.nome.toLowerCase().includes('combo')) {
    carrinhoTexto += `📦 ${itemNoCarrinho.nome.trim()}\n\n`;
  } else {
    carrinhoTexto += `🍫 ${itemNoCarrinho.nome.trim()}\n\n`; 
  } 

  carrinhoTexto += `*Quantidade:* ${itemNoCarrinho.qtd}\n`;
  carrinhoTexto += `*Preço:* ${precoUnitarioFormatado} *(${subtotalFormatado})*\n`;

  // 👉 NOVO TRECHO — ITENS INTERNOS DO COMBO
  if (itemNoCarrinho.itens_internos && itemNoCarrinho.itens_internos.length > 0) {
    carrinhoTexto += `*Itens do Combo:*\n`;

    itemNoCarrinho.itens_internos.forEach(subItem => {
      carrinhoTexto += `${subItem.qtd}x ${subItem.nome}\n`;
    });

    carrinhoTexto += `\n\n`;
  }

  carrinhoTexto += `----------------------------------------------------------\n\n`;
}

// --- FIM DA CORREÇÃO LÓGICA ---

// 7. Lógica de Desconto
let valorDoDesconto = 0;
let totalComDesconto = totalGeral;
let textoDoDesconto = "";
let descontoFormatado = "";

if (valorDoCupom && !isNaN(parseFloat(valorDoCupom)) && parseFloat(valorDoCupom) > 0) {
  const percentualDecimal = parseFloat(valorDoCupom) * 1; 
  // Ajuste conforme seu dado (ex: 0.25 ou 25)

  // Calcula o desconto teórico 
  let descontoCalculado = totalGeral * percentualDecimal;

  // --- APLICA O LIMITE --- 
  if (descontoCalculado > limiteDesconto) { 
    valorDoDesconto = limiteDesconto;
  } else {
    valorDoDesconto = descontoCalculado; 
  }

  totalComDesconto = totalGeral - valorDoDesconto;
  descontoFormatado = valorDoDesconto.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
  textoDoDesconto = `*💸→ DESCONTO:*\n_*-${descontoFormatado}*_\n\n`;
}

// --- NOVA LÓGICA DE AVALIAÇÃO DE MÍNIMOS (FRETE) ---
const VALOR_MINIMO_FRETE = 45.00; // Altere este valor se a regra do seu frete mudar
let freteAtingiuMinimo = false;
let valorFaltanteFrete = 0;

if (totalGeral >= VALOR_MINIMO_FRETE) {
    freteAtingiuMinimo = true;
} else {
    valorFaltanteFrete = VALOR_MINIMO_FRETE - totalGeral;
}
// --- FIM DA LÓGICA DO FRETE ---

// 8. Monta a mensagem final
let mensagemFinal = `*🛍️→ PEDIDO:*\n\n`;
mensagemFinal += carrinhoTexto;
if (valorDoDesconto > 0) {
  mensagemFinal += textoDoDesconto;
}
mensagemFinal += `*🪙→ VALOR PEDIDO:*\n`;
if (valorDoDesconto > 0) {
  mensagemFinal += `~${totalGeral.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' }).replace('.', ',')}~ *${totalComDesconto.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' }).replace('.', ',')}*\n\n`;
} else {
  mensagemFinal += `*${totalGeral.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' }).replace('.', ',')}*\n\n`;
}

// mensagemFinal += `*🛵→ FRETE:*\n`;
// mensagemFinal += `Aguardando cálculo...\n\n`;

// 3. Monta a variável 'salva_carrinho' para uso interno ou logs.
let salva_carrinho = `*🛍️→ PEDIDO:*\n\n`;
salva_carrinho += carrinhoTexto;
// Adiciona a linha do desconto somente se ele foi aplicado.
if (valorDoDesconto > 0) {
  salva_carrinho += textoDoDesconto;
}
salva_carrinho += `*🪙→ VALOR PEDIDO:*\n`;
if (valorDoDesconto > 0) {
  salva_carrinho += `~${totalGeral.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' }).replace('.', ',')}~ *${totalComDesconto.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' }).replace('.', ',')}*\n\n`;
} else {
  salva_carrinho += `*${totalGeral.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' }).replace('.', ',')}*\n\n`;
}
// ... (resto da sua lógica para montar a mensagemFinal)

// 9. Retorna os dados finais
return [{
  json: {
    Jid: sessao.jid,
    telefone_real: sessao.telefone_real,
    mensagemResposta: mensagemFinal,
    totalComDesconto: totalComDesconto.toFixed(2),
    totalSemDesconto: totalGeral.toFixed(2),
    print_carrinho: salva_carrinho,
    descontoFormatado: descontoFormatado,
    cupom_promo: dados.property_cupom,

    // Variáveis do Frete adicionadas à saída
    frete_atingiu_minimo: freteAtingiuMinimo,
    valor_faltante_frete: valorFaltanteFrete.toFixed(2),
    valor_faltante_frete_formatado: valorFaltanteFrete.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })
  }
}];

// --- CÓDIGO APRIMORADO PARA VERIFICAR VALOR MÍNIMO E CALCULAR A DIFERENÇA ---

/**
 * Analisa se o valor de um pedido atinge o valor mínimo e calcula quanto falta.
 * @param {number|string} valorDoPedido O valor total do pedido.
 * @param {number|string} valorMinimo O valor mínimo exigido.
 * @returns {object} Um objeto contendo se o mínimo foi atingido e o valor faltante.
 */
function analisarValorMinimo(valorDoPedido, valorMinimo) {
  // Converte as entradas para números de ponto flutuante.
  const pedido = parseFloat(valorDoPedido);
  const minimo = parseFloat(valorMinimo);

  // Retorna um resultado padrão em caso de erro.
  if (isNaN(pedido) || isNaN(minimo)) {
    return { atingeMinimo: false, valorFaltante: 0 };
  }

  const atingeMinimo = pedido >= minimo;
  let valorFaltante = 0;

  // Se não atingiu o mínimo, calcula a diferença.
  if (!atingeMinimo) {
    valorFaltante = minimo - pedido;
  }

  // Retorna um objeto com ambas as informações.
  return {
    atingeMinimo: atingeMinimo,
    valorFaltante: valorFaltante
  };
}

// --- Como usar no seu fluxo n8n ---

// 1. Pega os dados do seu nó anterior do PostgreSQL (já corrigido com o seu nome de nó).
